    "…わりぃ…": "...Sorry, I...",
    "…ん…効いた…けど平気": "...Mm. That landed. I'm okay.",
    "…ん、ちょっと考え事。気にしないで": "...Hm? Just thinking about something. Don't mind me.",
    "…ん。まあ、やるっす": "...Mm. Yeah, I'll do it.",
