    "…ゼロじゃないなら…まあ、いいよ。次はもう少し期待してる。": "...If it isn't zero... well, that works. I'll want a bit more next time.",
    "…ゼロじゃないなら、まあいい。次は期待してる": "...Not zero, so it'll do. Next time I expect more.",
