    "…タイミング": "...Timing.",
    "…タイミング、合わせて": "...The timing — match it.",
    "…チャンピオンのまま終わりか。…皮肉だね": "...It ends with me as champion. ...There's an irony in that.",
    "…テレビ。…っ、…やる。ありがとう": "...TV. ...Mm, I'm in. Thank you.",
    "…テレビ。…私なんかが。…でも、やる": "...TV. ...Someone like me. ...Still, I'm doing it.",
    "…テレビ。出る": "...TV. I'm in.",
