    "…バラエティか。笑わせにいく": "...A variety show. I will go get laughs.",
    "…バラエティか。笑わせにいこうかな": "...A variety show. Maybe I'll go get some laughs.",
    "…ファッションショー。みんなに見られるんだよね…": "...A fashion show. Everyone will be watching, won't they...",
    "…ファッションショー。人に見られるのか…": "...A fashion show. People will be watching...",
    "…ファッションショーか。キラキラしてそうだね": "...A fashion show, huh. Sounds like a lot of shine.",
