    "…フリーも悪くなかったけど、ここでのんびりやるよ": "...Freelance wasn't bad, but I'll take it easy here.",
    "…フリーも悪くなかったけど、ここでやってみるよ": "...Freelance wasn't bad, but I'll give this a try.",
    "…ブランドには口数の少なさが向いている。悪くない": "...Brands suit people who say little. Not bad.",
    "…プロレスもファッションも。…どっちも私のものだね": "...Wrestling, fashion. ...Both of them are mine.",
