    "…一つ勝った。…まだ先がある": "...One in hand. ...There's more ahead.",
    "…一人、片づけた。まだ立てる。手を抜く理由がない。次、来なよ": "...One cleared. I can still stand. No reason to spare anything. Next, come on.",
    "…一人、片づけたよ。息は上がってるけど、まだ立てる。次、来なよ": "...One down. Breathing hard, but I can still stand. Next, let's have you.",
