    "…一人片づけた。息は上がってるけど、退く理由はないよ。次、来なよ": "...One cleared. Breathing hard, but there's no reason to step back. Next, come on.",
    "…一人片づけたよ。息は上がってるけど、退く場面じゃない。次、来なよ": "...That's one cleared. I'm short of breath, but this isn't where I step back. Next, come on.",
