    "…下げない、の。…変わってるわね、社長は。…なら、その額のぶんは働くわ。": "...You're not cutting it. ...You're a strange one, Boss. ...Then I'll work for the figure.",
    "…下げないの。……こっちが折れた形ね。…わかった。その額に、体のほうを合わせるわ。": "...You won't cut it. ...So I'm the one who folded. ...Fine. I'll bring myself up to it.",
