    "…交代します": "...I'm switching in.",
    "…交代だ": "...Switching in.",
    "…交代ですわ": "...I am taking over.",
    "…人を変えられると思うほうが傲慢よ。今日のところは、諦めるわ": "...Thinking you can change a person is the arrogant part. I'll let today go.",
    "…今のあなたじゃ、わたしには届かない。また来なよ": "...You can't reach me as you are. Come back when you can.",
    "…今の団体に、恥はかかせない。だから勝つ。": "...I won't embarrass the place I'm with. So I win.",
    "…今日、急に掴めた気がする": "...Something landed today. Suddenly.",
    "…今日は、やらない": "...Not today.",
    "…今日は、休ませてもらおうかな": "...Think I'll take today off.",
    "…今日はいいかな。少し考えたいことがあって": "...I'll pass today. There's something I want to think through.",
    "…今日はわたしの勝ちだね。また次もよろしく": "...Today's mine, I think. Let's do it again sometime.",
    "…今日は持っていかれたね。…でも、これで終わりじゃない": "...You took this one. ...But it doesn't end here.",
