    "…体が、しんどい。…でも、やりたい": "...Everything aches. ...I still want to go.",
    "…体が、もう言うことを聞かない": "...The body won't answer me anymore.",
    "…体がしんどいな。…でも、まだやりたいんだけど": "...I'm running on empty. ...I'd still rather keep going, though.",
    "…体が先に落ちた。…頭は、まだだったんだけどね": "...The body dropped first. ...My head hadn't yet.",
