    "う…体がしんどいです…でも、でも頑張りたいのに…っ": "Ngh... everything is so heavy... but I want to keep going, I do...!",
    "う…体がつらい…でも、まだ頑張りたいのに…っ": "Ngh... it is so hard... and yet I want to keep going...",
    "う…嬉しい…っ…ありがとうございます": "Ngh... I am so glad...! Thank you very much.",
    "う…嬉しい…っ…ありがとよ…": "Ngh... I'm happy...! Thanks...",
    "う、うぅ…でも…立てます…": "Uu... but... I can still get up...",
    "う、うぅ…でも…立てますわ…": "N-Nngh... but... I can stand...",
